import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "lot"
PINS = {'site_furniture.py': 'ccdac82bca772392', 'tests/test_site_furniture.py': '42e41305bcf59662'}
EDITS = {'site_furniture.py': [('lines 181-182', 'SIGN_BEFORE_SHELTER = 1.0\nPIECE_GAP = 0.3           # daylight between two pieces along the band\n', 'SIGN_BEFORE_SHELTER = 1.0\n#: A SIGN ON A CURBED STREET STANDS 2 FT FROM THE CURB FACE to its nearest edge:\n#: PennDOT LTAP Tech Sheet 181, the urban lateral offset (1 ft where space is\n#: limited), the MUTCD\'s curbed-street minimum. A bus stop\'s flag speaks to the\n#: bus and to whoever would park there, so it stands at the curb and not at the\n#: back of the walk (0.127.0; the walker, walking cold run 9386: "it sohuld be\n#: closer to the road"). The stop signs answer the walker\'s 6 ft rule\n#: (`STOP_LATERAL_MIN`) instead, which `docs/STREET_RULES.md` records.\nCURB_SIGN_OFFSET = 2 * 0.3048\nPIECE_GAP = 0.3           # daylight between two pieces along the band\n'), ('lines 503-506', '    """The stop as a set -- shelter, bench inside it, sign before it -- at\n    the midpoint of the longest free stretch of ``kerb`` that holds it clear\n    of the cuts and of what already stands; nudged along in 3 m steps when\n    a lamp or a tree is in the way. Returns the pieces (possibly none)."""\n', '    """The stop as a set -- shelter, bench inside it, its flag before it at\n    the curb -- at the midpoint of the longest free stretch of ``kerb`` that\n    holds it clear of the cuts and of what already stands; nudged along in 3\n    m steps when a lamp or a tree is in the way. Returns the pieces (possibly\n    none).\n\n    THE FLAG AT THE CURB (0.127.0): turned to face along the road, its\n    plate\'s width runs across the walk, so its post stands\n    `CURB_SIGN_OFFSET` plus half that width in from the curb face. It stood\n    `BAND_INSET` in from the band\'s BACK edge until then, beside the\n    buildings\' walls and doors."""\n'), ('lines 508-510', '    sign_w, sign_d, _ = SPECIES["sign_post"]\n    outer = kerb.offset + kerb.sign * (road.sidewalk / 2.0 - BAND_INSET)\n    shelter_off = kerb.offset + kerb.sign * (road.sidewalk / 2.0 - SHELTER_INSET)\n', '    sign_w, sign_d, _ = SPECIES["sign_post"]\n    flag_off = kerb.offset - kerb.sign * (road.sidewalk / 2.0 - CURB_SIGN_OFFSET\n                                          - BLADE_DIMS[BLADE_AT_BUS_STOP][0] / 2.0)\n    shelter_off = kerb.offset + kerb.sign * (road.sidewalk / 2.0 - SHELTER_INSET)\n'), ('lines 541-541', '                             outer, 90.0, breaks=tag, blade=BLADE_AT_BUS_STOP)]\n', '                             flag_off, 90.0, breaks=tag, blade=BLADE_AT_BUS_STOP)]\n')], 'tests/test_site_furniture.py': [('lines 149-150', '    assert not [p for p in site_furniture.plan_furniture(roads) if p["species"] == "bus_shelter"]\n\n', '    assert not [p for p in site_furniture.plan_furniture(roads) if p["species"] == "bus_shelter"]\n\n\ndef test_the_bus_stop_flag_stands_at_the_curb():\n    """The flag\'s plate, turned to face along the road, has its near edge `CURB_SIGN_OFFSET` (2 ft, PennDOT TS 181)\n    from the curb face -- the walker, walking cold run 9386: "it sohuld be closer to the road" -- and stands nearer\n    the road than the shelter."""\n    assert abs(site_furniture.CURB_SIGN_OFFSET - 0.6096) < 1e-9\n    spec = _probe()\n    roads = site_streets.roads(spec)\n    pieces = site_furniture.plan_furniture(roads, spec["buildings"])\n    (flag,) = [p for p in pieces if p["species"] == "sign_post" and p["breaks"].startswith("stop@")]\n    (shelter,) = [p for p in pieces if p["species"] == "bus_shelter"]\n    road = roads[0]\n    plate_w = site_furniture.BLADE_DIMS[site_furniture.BLADE_AT_BUS_STOP][0]\n    curb = road.width / 2.0\n    near_edge = abs(flag["at"][1]) - plate_w / 2.0 - curb\n    assert abs(near_edge - site_furniture.CURB_SIGN_OFFSET) < 1e-3, (flag["at"], curb)\n    assert abs(flag["at"][1]) < abs(shelter["at"][1])\n\n')]}
NEW_FILES = {}
CHANGELOG = '## 0.127.0 - a bus stop\'s flag stands at the curb\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 10): a BUS STOP\nflag at the back of the sidewalk beside a building\'s wall and door -- "bus stop sign is for cars/buses so there is no\nparking ther...so it sohuld be closer to the road". `_bus_stop` stood the flag `BAND_INSET` in from the sidewalk\nband\'s BACK edge, the same line as the shelter\'s.\n\n### Changed\n- **The flag stands at the curb**: its plate, turned to face along the road, has its near edge `CURB_SIGN_OFFSET`\n  (2 ft, 0.6096 m) from the curb face -- PennDOT LTAP Tech Sheet 181\'s urban lateral offset where a curb exists, the\n  MUTCD\'s curbed-street minimum -- so its post stands 0.762 m in. On the probe street, 7.55 m from the centre line\n  to 5.76 m, the curb at 5.0. The shelter and bench keep their place at the back of the walk.\n\n### Not changed, and why\n- **The stop signs keep the walker\'s 6 ft rule** (`STOP_LATERAL_MIN`, `docs/STREET_RULES.md`). The MUTCD\'s 6 ft is\n  its offset where there is no curb; the factory\'s street rules record the walker\'s figure, and a reference fills a\n  blank rather than overriding a rule the walker gave. Said in `CURB_SIGN_OFFSET`\'s comment.\n- **Parking bays still run past a stop.** The walker\'s reason for the rule -- no parking where the bus pulls in --\n  asks `site_streets.bays` to leave the stop\'s length free, and `bays(road)` is computed from the road alone by five\n  modules (meters, parked cars, the getaway van, poles) while the stop is placed later against what already stands.\n  Filed with the finding as its second half.\n\n### Tests\n- `tests/test_site_furniture.py::test_the_bus_stop_flag_stands_at_the_curb` (new): the plate\'s near edge 2 ft from\n  the curb face, nearer the road than the shelter. It fails on 0.126.1 on behaviour (the flag at 7.55 m, the curb at\n  5.0 m).\n\n'
OLD_VERSION, NEW_VERSION = 'Lot 0.126.1', 'Lot 0.127.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: lot/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: lot/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: lot/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: lot/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## " + OLD_VERSION.split()[-1].encode() + b" "):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in lot/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
